#!/usr/bin/env python3
# patch_smart_select.py - flag dropdowns for Smart Match settings + Done button
# Usage (from the project folder omegle-clone):  python patch_smart_select.py        (dry run)
#                                               python patch_smart_select.py --apply
import sys, os, re, base64
APPLY = '--apply' in sys.argv
V = "20261022-1"
PUB = 'public' if os.path.isdir('public') else '.'
